import { Suspense, lazy, useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import customWallpaper from "../assets/custom/wallpaper.jpeg";
import type { Work } from "../schema";
import "./player.css";

// Start downloading the phone runtime immediately, but keep it out of the
// entry chunk so it can load in parallel with the work JSON on mobile.
const phoneModule = import("../Phone");
const Phone = lazy(() =>
  phoneModule.then((module) => ({ default: module.Phone })),
);

// work.json is generated by scripts/story.mjs, which validates the complete
// story during the build. Avoid repeating a deep Zod parse of every message and
// product on low-powered mobile Safari before showing the lock screen.
function readBuiltWork(value: unknown): Work {
  if (!value || typeof value !== "object")
    throw new Error("作品数据无效");
  const work = value as Partial<Work>;
  if (
    typeof work.id !== "string" ||
    !work.phone ||
    !Array.isArray(work.apps) ||
    !work.data || typeof work.data !== "object" ||
    !Array.isArray(work.nodes)
  ) {
    throw new Error("作品数据不完整，请重新部署最新构建");
  }
  return work as Work;
}
function StoryPlayer() {
  const [work, setWork] = useState<Work | null>(null),
    [error, setError] = useState("");

  // iOS Safari can still chain a vertical touch gesture to the outer page even
  // when the page root is fixed. Freeze the document and allow vertical touch
  // movement only when it can scroll a genuine inner list/chat pane.
  useEffect(() => {
    const html = document.documentElement;
    const body = document.body;
    const root = document.getElementById("root");
    const elements = [html, body, root].filter(
      (value): value is HTMLElement => value instanceof HTMLElement,
    );
    const before = elements.map((el) => ({
      el,
      css: {
        position: el.style.position,
        inset: el.style.inset,
        width: el.style.width,
        height: el.style.height,
        overflow: el.style.overflow,
        overscrollBehavior: el.style.overscrollBehavior,
      },
    }));
    for (const el of elements) {
      el.style.overflow = "hidden";
      el.style.overscrollBehavior = "none";
    }
    for (const el of [html, body, root]) {
      if (!el) continue;
      el.style.position = "fixed";
      el.style.inset = "0";
      el.style.width = "100%";
      el.style.height = "100%";
    }

    let startX = 0;
    let startY = 0;
    let startPane: HTMLElement | null = null;
    const findScrollable = (target: EventTarget | null) => {
      let node = target instanceof HTMLElement ? target : null;
      while (node && node !== root) {
        const overflowY = window.getComputedStyle(node).overflowY;
        if (
          (overflowY === "auto" || overflowY === "scroll" || overflowY === "overlay") &&
          node.scrollHeight > node.clientHeight + 1
        ) return node;
        node = node.parentElement;
      }
      return null;
    };
    const onTouchStart = (event: TouchEvent) => {
      if (event.touches.length !== 1) {
        startPane = null;
        return;
      }
      const touch = event.touches[0];
      startX = touch.clientX;
      startY = touch.clientY;
      startPane = findScrollable(event.target);
    };
    const onTouchMove = (event: TouchEvent) => {
      if (event.touches.length !== 1) return;
      const touch = event.touches[0];
      const deltaX = touch.clientX - startX;
      const deltaY = touch.clientY - startY;
      if (Math.abs(deltaY) < 2 || Math.abs(deltaX) > Math.abs(deltaY)) return;

      const pane = findScrollable(event.target) || startPane;
      if (!pane || pane.scrollHeight <= pane.clientHeight + 1) {
        if (event.cancelable) event.preventDefault();
        return;
      }
      const maxScroll = pane.scrollHeight - pane.clientHeight;
      const canScroll = deltaY < 0
        ? pane.scrollTop < maxScroll - 1
        : pane.scrollTop > 1;
      // Stop overscroll from escaping a list at its top/bottom to the page.
      if (!canScroll && event.cancelable) event.preventDefault();
    };
    document.addEventListener("touchstart", onTouchStart, { capture: true, passive: true });
    document.addEventListener("touchmove", onTouchMove, { capture: true, passive: false });
    return () => {
      document.removeEventListener("touchstart", onTouchStart, true);
      document.removeEventListener("touchmove", onTouchMove, true);
      for (const entry of before) {
        Object.assign(entry.el.style, entry.css);
      }
    };
  }, []);

  useEffect(() => {
    const abort = new AbortController();
    fetch(
      new URLSearchParams(location.search).get("preview") === "test"
        ? "./test-work.json"
        : new URLSearchParams(location.search).get("template") === "blank"
          ? "./blank-work.json"
          : "./work.json",
      { signal: abort.signal },
    )
      .then((r) => {
        if (!r.ok) throw Error("缺少作品文件，请运行 npm run story:build");
        return r.json();
      })
      .then(async (x) => {
        const w = readBuiltWork(x);
        document.title =
          w.title === "捡手机" ? "捡手机" : w.title + " · 捡手机";

        // Mount the phone immediately after the work JSON is ready.
        // Wallpaper decoding must never block startup on mobile Safari.
        if (w.phone.wallpaper === "dog") {
          const image = new Image();
          image.src = customWallpaper;
          void image.decode().catch(() => {});
        }
        setWork(w);
      })
      .catch((e) => {
        if (e.name !== "AbortError") setError(String(e));
      });
    return () => abort.abort();
  }, []);
  return (
    <main className="story-runtime">
      {work ? (
        <Suspense fallback={<p role="status">正在打开手机…</p>}>
          <Phone work={work} />
        </Suspense>
      ) : (
        <p role="status">{error || "正在打开手机…"}</p>
      )}
    </main>
  );
}
createRoot(document.getElementById("root")!).render(<StoryPlayer />);
